import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { SpotDetail } from "@/components/spot-detail";
import { getSpotById, touristSpots } from "@/lib/spots";

export function generateStaticParams() {
  return touristSpots.map((spot) => ({ id: spot.id }));
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ id: string }>;
}): Promise<Metadata> {
  const { id } = await params;
  const spot = getSpotById(id);
  if (!spot) return { title: "Place not found" };
  return {
    title: spot.name,
    description: spot.description,
    openGraph: {
      title: `${spot.name} — Tour Partner`,
      description: spot.description,
    },
  };
}

export default async function SpotPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = await params;
  const spot = getSpotById(id);
  if (!spot) notFound();

  return (
    <>
      <SpotDetail spot={spot} />
      <footer className="site-footer detail-footer">
        <Link className="footer-brand" href="/">TOUR PARTNER</Link>
        <span>Thoughtful journeys through Bangladesh.</span>
        <a href={spot.images[0].source} rel="noreferrer" target="_blank">
          Photo by {spot.images[0].attribution} · {spot.images[0].license}
        </a>
      </footer>
    </>
  );
}
